.cart-shipping-info {
  width: 100%;
  padding: 8px 6px;
  margin: 5px 0;
  font-size: 13px;
  box-sizing: border-box;
}

/* Free shipping */
.shipping-free {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 9px 12px;
  border-radius: 6px;
  background: #f1f8f3;
  color: #2e7d32;
  font-size: 13px;
}

/* Heading */
.shipping-title {
  font-weight: 600;
  font-size: 13px;
  margin-bottom: 6px;
  color: #333;
}

/* Shipping rows */
.shipping-options {
  border: 1px solid #e5e5e5;
  border-radius: 6px;
  overflow: hidden;
  background: #fff;
}

.shipping-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  line-height: 1.4;
}

.shipping-option + .shipping-option {
  border-top: 1px solid #eeeeee;
}

.shipping-method {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #444;
}

.shipping-option strong {
  color: #222;
  font-weight: 600;
}

/* Small dots */
.shipping-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.cod-dot {
  background: #777;
}

.prepaid-dot {
  background: #2e7d32;
}

/* Saving message */
.shipping-note {
  margin-top: 6px;
  font-size: 11px;
  color: #2e7d32;
  text-align: right;
}



.announcement-bar {
  background: #88B950;
  color: #fff;
  overflow: hidden;
  padding:12px 0px 13px 0px;
}

.announcement-wrapper {
  width: 100%;
  overflow: hidden;
}

.announcement-track {
  display: flex;
  width: max-content;
  animation: announcementScroll linear infinite;
  animation-duration: 28s;
}

.announcement-item {
  
  display: flex;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
  font-size: 14px;
  flex:0 0 16%;
  font-family: 'Goli',sans-serif;
font-weight: 500;
font-size: 14px;
line-height: 1.2;
color:#FFFFFF;
}
.announcement-cta {
  margin-left: 8px;
  color: #fff;
  font-weight: 500;
  text-decoration: underline;
  cursor: pointer;
}

.announcement-cta:hover {
  opacity: 0.85;
}
/* 🔥 CONTINUOUS SCROLL */
@keyframes announcementScroll {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-50%);
  }
}

/* pause on hover */
.announcement-bar:hover .announcement-track {
  animation-play-state: paused;
}

