      /* ITEM */
      .rovique-collections__item {
        text-align: center;
        text-decoration: none;
        color: #000;
        width: 130px;
        height: 130px;
      }

      .rovique-collections__image img {
        width: 100%;
        
        display: block;
      }

      /* TITLE */
      .rovique-collections__title {
        font-family: 'Goli', sans-serif;
        font-size: 18px;
        font-weight: 500;
        line-height:1.2;
        color:#1D1D1D;
      }

      /* HOVER */
    .rovique-collections__item {
      transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1);
      will-change: transform;
    }

    /* HOVER (image + text together) */
    .rovique-collections__item:hover {
      transform: translateY(-2px) scale(1.05);
      transition: 0.6s;
    }

      /* MOBILE */
      @media (max-width: 768px) {
