.review-popup{

    position:fixed;

    inset:0;

    background:#000;

    z-index:9999;

    display:flex;

    align-items:center;

    justify-content:center;

    opacity:0;

    visibility:hidden;

    transition:.35s ease;

    padding:20px;
}

.review-popup.active{

    opacity:1;

    visibility:visible;
}


/* IMAGE */

.review-popup-image{

    width:100%;

    max-width:500px;

    max-height:90vh;

    object-fit:contain;

    border-radius:20px;
}


/* CLOSE */

.review-popup-close{

    position:absolute;
    top:20px;
    right:20px;
    background:#fff;
    color:#000;
    font-size:16px;
    cursor:pointer;
    

}


