.rovique-reviews__slider {
  position: relative;
}

/* LEFT & RIGHT ARROWS */
.rovique-reviews__arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;

  width: 35px;
  height: 35px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid #84B547;
  border-radius: 50%;

  background: #fff;
  color: #84B547;

  font-size: 30px;
  line-height: 1;

  cursor: pointer;
  transition: 0.3s ease;

  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.12);
}

.rovique-reviews__arrow:hover {
  background: #84B547;
  color: #fff;
}

/* LEFT SIDE */
.rovique-reviews__arrow--prev {
  left: -60px;
}

/* RIGHT SIDE */
.rovique-reviews__arrow--next {
  right: -60px;
}
